/bin/bash -lc "python - <<'PY'
import numpy as np, mujoco
from sim import Sim

sim=Sim(); m=sim.model; d=sim.data
lid=m.body('left_finger').id
rid=m.body('right_finger').id
jmin=m.jnt_range[:7,0]; jmax=m.jnt_range[:7,1]

# seed arm to reasonable posture and open fingers
q=d.qpos[:7].copy()
d.qpos[7]=0.04; d.qpos[8]=0.04
mujoco.mj_forward(m,d)

def mid_pos():
    return 0.5*(d.xpos[lid]+d.xpos[rid])

def mid_jac():
    jl=np.zeros((3,m.nv)); jr=np.zeros((3,m.nv))
    mujoco.mj_jacBodyCom(m,d,jl,None,lid)
    mujoco.mj_jacBodyCom(m,d,jr,None,rid)
    return 0.5*(jl[:,:7]+jr[:,:7])

def solve(target,q0,it=400):
    q=q0.copy()
    for k in range(it):
        d.qpos[:7]=q; d.qvel[:7]=0; d.qpos[7]=0.04; d.qpos[8]=0.04; mujoco.mj_forward(m,d)
        e=target-mid_pos()
        if np.linalg.norm(e)<0.003:
            return q,True,np.linalg.norm(e)
        J=mid_jac();
        dq=J.T@np.linalg.solve(J@J.T+2e-3*np.eye(3),e)
        q=np.clip(q+0.8*dq,jmin,jmax)
    d.qpos[:7]=q; mujoco.mj_forward(m,d)
    return q,False,np.linalg.norm(target-mid_pos())

cup=np.array([0.55,0.15,0.432])
targets=[cup+np.array([0,0,0.15]),cup+np.array([0,0,0.07]),cup+np.array([0,0,0.03]),cup+np.array([0,0,0.0]),cup+np.array([0,0,-0.02])]
for t in targets:
    q,ok,err=solve(t,q)
    d.qpos[:7]=q; d.qpos[7]=0.04; d.qpos[8]=0.04; mujoco.mj_forward(m,d)
    l=d.xpos[lid].copy();r=d.xpos[rid].copy();
    print('target',np.round(t,3),'ok',ok,'err',round(err,4),'mid',np.round(mid_pos(),3),'sep',round(np.linalg.norm(r-l),4),'q',np.round(q,3))
PY"

